        ["As you guide the unstable soul to the underworld, they thank you by sharing some of their [Skill] knowledge."] = "Mientras guías al alma inestable al inframundo, te lo agradecen compartiendo algunos de sus conocimientos [Skill].",
        ["You gain [number] [Skill] XP."] = "Obtienes [número] [Skill] XP.",
        ["The lost soul disappears before you could guide it onwards."] = "El alma perdida desaparece antes de que puedas guiarla hacia adelante.",
    },
    ["Ur-lun"] = {
        ["At the next council meeting, I'm going to recommend that we change the guards uniforms to be red."] = "En la próxima reunión del consejo, recomendaré que cambiemos los uniformes de los guardias para que sean rojos.",
        ["Why?"] = "¿Por qué?",
        ["We have surface-dwellers coming down into our mines and our city now, and remember that they don't have very good eyesight. I worry that they can't see our guards very clearly in the dark. It is important for a guard to be seen."] = "Ahora tenemos habitantes de la superficie que bajan a nuestras minas y a nuestra ciudad, y recuerden que no tienen muy buena vista. Me preocupa que no puedan ver a nuestros guardias con mucha claridad en la oscuridad. Es importante que se vea a un guardia.",
        ["You have a point. But i don't think red would be the best colour. It's the colour of blood, so it might give the wrong impression."] = "Tienes razón. Pero no creo que el rojo sea el mejor color. Es el color de la sangre, por lo que podría dar una impresión equivocada.",
        ["What colour do you suggest, then?"] = "¿Qué color sugieres entonces?",
        ["I suggest green. I have heard that the plants that grow on the surface are mostly green, so surface-dwellers might find that colour soothing."] = "Sugiero verde. He oído que las plantas que crecen en la superficie son en su mayoría verdes, por lo que los habitantes de la superficie pueden encontrar ese color relajante.",
        ["No, I disagree. Guards should not be soothing, they should be seen as formidable. Red will give the correct impression."] = "No, no estoy de acuerdo. Los guardias no deben ser tranquilizadores, sino que deben ser vistos como formidables. El rojo dará la impresión correcta.",
        ["Oh, hello surface-dweller. We were just discussing some council business."] = "Oh, hola habitante de la superficie. Estábamos discutiendo algunos asuntos del consejo.",
        ["Do you want me to pick an armour colour for you?"] = "¿Quieres que elija un color de armadura para ti?",
        ["No, thank you. We don't one single goblin make decisions, and certainly not an outsider!"] = "No, gracias. No somos un solo duende el que toma decisiones, ¡y menos aún un extraño!",
        ["But we could do with an opinion. What armour colour do you think is best?"] = "Pero nos vendría bien una opinión. ¿Qué color de armadura crees que es mejor?",
        ["Red."] = "Rojo.",
        ["Thank you, surface-dweller. That's what I'll be recommending in the next meeting."] = "Gracias, habitante de la superficie. Eso es lo que recomendaré en la próxima reunión.",
        ["Green."] = "Verde.",
        ["I think the guards are fine as they are."] = "Creo que los guardias están bien tal como están.",
        ["Perhaps you're right. Not making any change would certainly be the easiest option!"] = "Quizás tengas razón. ¡No hacer ningún cambio sería sin duda la opción más fácil!",
        ["I think I've been here before..."] = "Creo que ya he estado aquí antes...",
        ["Oh? How so?"] = "¿Ah? ¿Cómo es eso?",
        ["This is a lot like a conversation I had with some goblins on the surface."] = "Esto se parece mucho a una conversación que tuve con algunos duendes en la superficie.",
        ["Really? Which armour colour did they pick?"] = "¿En serio? ¿Qué color de armadura eligieron?",
        ["They ended up with the same armour colour that they started with!"] = "¡Terminaron con el mismo color de armadura con el que empezaron!",
        ["You know, I think that's probably what we'll end up doing."] = "Sabes, creo que eso es probablemente lo que terminaremos haciendo.",
    },
    ["Ur-meg"] = {
        ["*When speaking to Ur-Meg in Dorgesh-kaan*"] = "*Al hablar con Ur-Meg en Dorgesh-kaan*",
        ["Oh dear..."] = "Dios mío...",
        ["What's the matter?"] = "¿Qué pasa?",
        ["I'm worried. I think the Council is neglecting a big issue. I tried to bring it up at the last meeting, but they didn't pay attention."] = "Estoy preocupado. Creo que el Consejo está descuidando una cuestión importante. Intenté sacar el tema en la última reunión, pero no me prestaron atención.",
        ["What issue?"] = "¿Qué problema?",
        ["I'm very happy for you humans to come down to the city, but what about...them?"] = "Estoy muy feliz de que ustedes, los humanos, vengan a la ciudad, pero ¿qué pasa con... ellos?",
        ["What about who?"] = "¿Y quién?",
        ["Them! *whispers* The G-O-D-S."] = "¡Ellos! *susurra* Los DIOSES.",
        ["The gods?"] = "¿Los dioses?",
        ["Don't say it! What if they hear?"] = "¡No lo digas! ¿Qué pasa si escuchan?",
        ["Select an option"] = "Seleccione una opción",
        ["Why are you scared of the gods?"] = "¿Por qué tienes miedo de los dioses?",
        ["Because they're so powerful, of course! In the time of the great war, they forced all the goblin tribes to fight one another. Our ancestors weren't powerful enough to stand up to them. We've hidden down here for this long, but now the way to the surface is open, what if they find us again?"] = "¡Porque son muy poderosos, por supuesto! En la época de la gran guerra, obligaron a todas las tribus de duendes a luchar entre sí. Nuestros antepasados ​​no eran lo suficientemente poderosos para hacerles frente. Nos hemos escondido aquí durante tanto tiempo, pero ahora el camino a la superficie está abierto, ¿y si nos encuentran de nuevo?",
        ["You don't need to worry!"] = "¡No necesitas preocuparte!",
        ["I don't?"] = "¿No?",
        ["The god wars are over! The gods don't intervene directly in the affairs of mortals any more."] = "¡Las guerras de dioses han terminado! Los dioses ya no intervienen directamente en los asuntos de los mortales.",
        ["Are you sure?"] = "¿Estás seguro?",
        ["Yes!"] = "¡Sí!",
        ["I do hope you're right! I still can't help being worried, though."] = "¡Espero que tengas razón! Aunque todavía no puedo evitar preocuparme.",
        ["Don't you want to worship the god of the goblins?"] = "¿No quieres adorar al dios de los duendes?",
        ["No! How could you even suggest that? We're not going to worship some supernatural being just because it's bigger and more powerful than us. It may seem to you that we're cowardly, hiding here from the gods all this time, but I know that every Dorgeshuun would rather die than submit to the rule of any god."] = "¡No! ¿Cómo pudiste siquiera sugerir eso? No vamos a adorar a un ser sobrenatural sólo porque es más grande y más poderoso que nosotros. Puede que te parezca que somos cobardes al escondernos aquí de los dioses todo este tiempo, pero sé que cada Dorgeshuun preferiría morir antes que someterse al gobierno de cualquier dios.",
        ["Goodbye"] = "Adiós",
        ["Goodbye."] = "Adiós.",
    },
    ["Ur-pel"] = {
        ["At the next council meeting, I'm going to recommend that we change the guards uniforms to be red."] = "En la próxima reunión del consejo, voy a recomendar que cambiemos los uniformes de los guardias para que sean rojos.",
