        ["Oh, hello surface-dweller. We were just discussing some council business."] = "Oh, hola habitante de la superficie. Estábamos discutiendo algunos asuntos del consejo.",
        ["Do you want me to pick an armour colour for you?"] = "¿Quieres que elija un color de armadura para ti?",
        ["No, thank you. We don't one single goblin make decisions, and certainly not an outsider!"] = "No, gracias. No somos un solo duende el que toma decisiones, ¡y menos aún un extraño!",
        ["But we could do with an opinion. What armour colour do you think is best?"] = "Pero nos vendría bien una opinión. ¿Qué color de armadura crees que es mejor?",
        ["Red."] = "Rojo.",
        ["Thank you, surface-dweller. That's what I'll be recommending in the next meeting."] = "Gracias, habitante de la superficie. Eso es lo que recomendaré en la próxima reunión.",
        ["Green."] = "Verde.",
        ["I think the guards are fine as they are."] = "Creo que los guardias están bien tal como están.",
        ["Perhaps you're right. Not making any change would certainly be the easiest option!"] = "Quizás tengas razón. ¡No hacer ningún cambio sería sin duda la opción más fácil!",
        ["I think I've been here before..."] = "Creo que ya he estado aquí antes...",
        ["Oh? How so?"] = "¿Ah? ¿Cómo es eso?",
        ["This is a lot like a conversation I had with some goblins on the surface."] = "Esto se parece mucho a una conversación que tuve con algunos duendes en la superficie.",
        ["Really? Which armour colour did they pick?"] = "¿En serio? ¿Qué color de armadura eligieron?",
        ["They ended up with the same armour colour that they started with!"] = "¡Terminaron con el mismo color de armadura con el que empezaron!",
        ["You know, I think that's probably what we'll end up doing."] = "Sabes, creo que eso es probablemente lo que terminaremos haciendo.",
    },
    ["Ur-taal"] = {
        ["*When speaking to Ur-taal or Ur-zek in Dorgesh-kaan*"] = "*Al hablar con Ur-taal o Ur-zek en Dorgesh-kaan*",
        ["I think that Ur-tag is trying to move too quickly. First, he opens the city to humans, and now he wants to invite these dwarves into the city. I think we should exercise more caution in dealing with surface-dwellers."] = "Creo que Ur-tag está intentando moverse demasiado rápido. Primero, abre la ciudad a los humanos y ahora quiere invitar a estos enanos a la ciudad. Creo que deberíamos tener más cautela al tratar con los habitantes de la superficie.",
        ["The dwarves are not surface dwellers. They live in an underground city, like us!"] = "Los enanos no son habitantes de la superficie. ¡Viven en una ciudad subterránea, como nosotros!",
        ["Why does that mean we can trust them? Are you forgetting the machine that nearly destroyed us was made by dwarves?"] = "¿Por qué eso significa que podemos confiar en ellos? ¿Olvidas que la máquina que casi nos destruye fue construida por enanos?",
        ["You shouldn't judge all dwarves because of that!"] = "¡No deberías juzgar a todos los enanos por eso!",
        ["I know that! And I know not all humans want to kill us, but I still never thought we should open the city."] = "¡Lo sé! Y sé que no todos los humanos quieren matarnos, pero aun así nunca pensé que deberíamos abrir la ciudad.",
        ["You can't deny it's done some good. Think of how happy everyone is trying surface foods in the market!"] = "No puedes negar que ha hecho algo bueno. ¡Piense en lo felices que están todos al probar los alimentos de superficie en el mercado!",
        ["I'm not denying that, I just don't think it's worth the risk. Our guards have their work cut out as it is, protecting us from renegade humans, without having to worry about dwarves as well."] = "No lo niego, simplemente no creo que valga la pena correr el riesgo. Nuestros guardias tienen mucho trabajo por delante, protegiéndonos de los humanos renegados, sin tener que preocuparnos también por los enanos.",
        ["Please don't be offended by my friend's attitude, surface- dweller. I'm sure you understand why we need to be cautious."] = "Por favor, no te ofendas por la actitud de mi amigo, habitante de la superficie. Estoy seguro de que comprende por qué debemos ser cautelosos.",
        ["Of course."] = "Por supuesto.",
    },
    ["Ur-tag"] = {
        ["Headman Ur-tag, I cannot stress enough how important it is that this train link be completed on time. The mining companies have taken out considerable loans..."] = "Jefe Ur-tag, no puedo enfatizar lo suficiente lo importante que es que este enlace de tren se complete a tiempo. Las empresas mineras han obtenido préstamos considerables...",
        ["I understand your concerns, Ambassador, but you must realise that the discoveries must change the whole schedule. To remove them too hurriedly would be a crime against knowledge."] = "Entiendo sus preocupaciones, Embajador, pero debe comprender que los descubrimientos deben cambiar todo el calendario. Eliminarlos demasiado apresuradamente sería un crimen contra el conocimiento.",
        ["Greetings, surface-dweller. Welcome to Dorgesh-Kaan."] = "Saludos, habitante de la superficie. Bienvenido a Dorgesh-Kaan.",
        ["Select an Option"] = "Selecciona una opción",
        ["What are you arguing about?"] = "¿De qué estás discutiendo?",
        ["What are you talking about?"] = "¿De qué estás hablando?",
        ["It's the new underground train link being built between our city and the dwarven city of Keldagrim."] = "Es el nuevo enlace de tren subterráneo que se está construyendo entre nuestra ciudad y la ciudad enana de Keldagrim.",
        ["Shh! What if he's a human spy come to steal our dwarven engineering secrets?"] = "¡Shh! ¿Qué pasa si es un espía humano que viene a robar nuestros secretos de ingeniería enanos?",
        ["What can I do in the city?"] = "¿Qué puedo hacer en la ciudad?",
        ["Why don't you visit the market? I hear there is quite a craze for surface foods at the moment, so you might be able to sell something there."] = "¿Por qué no visitas el mercado? He oído que hay una gran moda por los alimentos de superficie en este momento, por lo que es posible que puedas vender algo allí.",
        ["You might also want to visit the caves to the south of the city. There are many monsters to fight there, and Zanik tells me she has also found ways to cross over their heads!"] = "Quizás también quieras visitar las cuevas al sur de la ciudad. ¡Hay muchos monstruos contra los que luchar allí, y Zanik me dice que también ha encontrado formas de pasar por encima de sus cabezas!",
        ["Why did you decide to open the city?"] = "¿Por qué decidiste abrir la ciudad?",
        ["For trade, and for fostering goodwill between races! I am sure that it will benefit both our races."] = "¡Por el comercio y por fomentar la buena voluntad entre razas! Estoy seguro de que beneficiará a ambas razas.",
        ["May I have permission to sell food in the market?"] = "¿Puedo tener permiso para vender comida en el mercado?",
        ["Of course you can."] = "Por supuesto que puedes.",
        ["I want to talk about the Kyzaj Tournament."] = "Quiero hablar sobre el Torneo Kyzaj.",
        ["Yes. Thank you again. You did everything you could and we are safer because of it."] = "Sí. Gracias de nuevo. Hiciste todo lo que pudiste y estamos más seguros gracias a ello.",
        ["How are things going?"] = "¿Cómo van las cosas?",
        ["I was concerned to hear that Graardor rejected Zanik's authority, but we've not had any trouble. The Bandosians cleared out almost immediately and haven't returned. They don't seem interested in us any more. There's always the possibility that they'll come after us again, but we're working on better ways to block their access."] = "Me preocupó escuchar que Graardor rechazó la autoridad de Zanik, pero no hemos tenido ningún problema. Los bandosianos se marcharon casi de inmediato y no han regresado. Ya no parecen interesados ​​en nosotros. Siempre existe la posibilidad de que vuelvan a perseguirnos, pero estamos trabajando en mejores formas de bloquear su acceso.",
        ["What do you think about Zanik?"] = "¿Qué opinas sobre Zanik?",
        ["I can only hope that she finds peace on Yu'biusk, one way or the other. Thank you for giving her that opportunity."] = "Sólo puedo esperar que encuentre la paz en Yu'biusk, de una forma u otra. Gracias por darle esa oportunidad.",
        ["Goodbye."] = "Adiós.",
    },
    ["Ur-vass"] = {
        ["Ah. Player, I presume?"] = "Ah. Player, ¿supongo?",
        ["That's me."] = "Ese soy yo.",
        ["Pleased to meet you. On behalf of the Dorgeshuun Council, I should say how grateful we are that you saved our city."] = "Encantado de conocerte. En nombre del Consejo Dorgeshuun, debo decir lo agradecidos que estamos de que haya salvado nuestra ciudad.",
        ["Ah, Player. It is always a pleasure to meet someone who has become part of Dorgeshuun history. I trust you like the statue we made of you and Zanik?"] = "Ah, Player. Siempre es un placer conocer a alguien que ha pasado a formar parte de la historia de Dorgeshuun. ¿Confío en que te guste la estatua que hicimos de ti y Zanik?",
        ["**Select an option**"] = "**Seleccione una opción**",
        ["It's very good."] = "Es muy bueno.",
        ["Thank you. I will pass on your compliments to the sculptor."] = "Gracias. Transmitiré sus felicitaciones al escultor.",
        ["It looks nothing like me!"] = "¡No se parece en nada a mí!",
        ["I'm afraid the sculptor doesn't have much experience carving human figures. It took him several tries to get the proportions right, so I don't think he can improve much on what he's done."] = "Me temo que el escultor no tiene mucha experiencia tallando figuras humanas. Le tomó varios intentos lograr las proporciones correctas, por lo que no creo que pueda mejorar mucho lo que ha hecho.",
        ["I don't like the pose."] = "No me gusta la pose.",
        ["Oh, I'm. sorry to hear that. Actually, the sculptor made sketches of several different ideas. If you like, I could have him install a statue with a different pose."] = "Oh, lo soy. lamento escuchar eso. En realidad, el escultor hizo bocetos de varias ideas diferentes. Si quieres, podría pedirle que instale una estatua con una pose diferente.",
        ["Yes, please change the statue."] = "Sí, cambia la estatua.",
        ["The pose is alright as it is."] = "La pose está bien tal como está.",
        ["That's good to hear."] = "Es bueno escucharlo.",
    },
    ["Ur-zek"] = {
        ["*When speaking to Ur-taal or Ur-zek in Dorgesh-kaan*"] = "*Al hablar con Ur-taal o Ur-zek en Dorgesh-kaan*",
        ["I think that Ur-tag is trying to move too quickly. First, he opens the city to humans, and now he wants to invite these dwarves into the city. I think we should exercise more caution in dealing with surface-dwellers."] = "Creo que Ur-tag está intentando moverse demasiado rápido. Primero, abre la ciudad a los humanos y ahora quiere invitar a estos enanos a la ciudad. Creo que deberíamos tener más cautela al tratar con los habitantes de la superficie.",
        ["The dwarves are not surface dwellers. They live in an underground city, like us!"] = "Los enanos no son habitantes de la superficie. ¡Viven en una ciudad subterránea, como nosotros!",
        ["Why does that mean we can trust them? Are you forgetting the machine that nearly destroyed us was made by dwarves?"] = "¿Por qué eso significa que podemos confiar en ellos? ¿Olvidas que la máquina que casi nos destruye fue construida por enanos?",
        ["You shouldn't judge all dwarves because of that!"] = "¡No deberías juzgar a todos los enanos por eso!",
        ["I know that! And I know not all humans want to kill us, but I still never thought we should open the city."] = "¡Lo sé! Y sé que no todos los humanos quieren matarnos, pero aun así nunca pensé que deberíamos abrir la ciudad.",
        ["You can't deny it's done some good. Think of how happy everyone is trying surface foods in the market!"] = "No puedes negar que ha hecho algo bueno. ¡Piense en lo felices que están todos al probar los alimentos de superficie en el mercado!",
        ["I'm not denying that, I just don't think it's worth the risk. Our guards have their work cut out as it is, protecting us from renegade humans, without having to worry about dwarves as well."] = "No lo niego, simplemente no creo que valga la pena correr el riesgo. Nuestros guardias tienen mucho trabajo por delante, protegiéndonos de los humanos renegados, sin tener que preocuparnos también por los enanos.",
        ["Please don't be offended by my friend's attitude, surface- dweller. I'm sure you understand why we need to be cautious."] = "Por favor, no te ofendas por la actitud de mi amigo, habitante de la superficie. Estoy seguro de que comprende por qué debemos ser cautelosos.",
        ["Of course."] = "Por supuesto.",
    },
    ["Urbi"] = {
        ["*When talking to Urbi in Sophanem.*"] = "*Al hablar con Urbi en Sophanem.*",
        ["Hello there; are you interested in any of my fine daggers? Ideal for slipping under desert robes to give your enemies a nasty surprise..."] = "Hola; ¿Estás interesado en alguno de mis excelentes daggers? Ideal para esconderse bajo las túnicas del desierto y darles a tus enemigos una desagradable sorpresa...",
        ["Select an option"] = "Seleccione una opción",
        ["I'm looking for daggers, yes."] = "Estoy buscando a daggers, sí.",
        ["I'd rather help you in return for better prices."] = "Prefiero ayudarte a cambio de mejores precios.",
        ["I think it will take months for me to return to normal business. If you can wait that long, however, I may have tasks for you."] = "Creo que me llevará meses volver a la normalidad. Sin embargo, si puedes esperar tanto, es posible que tenga tareas para ti.",
        ["No thanks."] = "No, gracias.",
    },
    ["Uri"] = {
        ["*When spoken to in the correct costume and after wearing the correct outfit, one of these will be said at random*"] = "*Cuando se le hable con el disfraz correcto y después de usar el atuendo correcto, se dirá uno de estos al azar*",
        ["Once, I was a poor man, but then I found a party hat."] = "Una vez fui un hombre pobre, pero luego encontré un sombrero de fiesta.",
        ["There were three goblins in a bar, which one left first?"] = "Había tres duendes en un bar, ¿cuál salió primero?",
        ["Would you like to buy a pewter spoon?"] = "¿Te gustaría comprar una cuchara de peltre?",
        ["In the end, only the three-legged survive."] = "Al final, solo sobreviven los de tres patas.",
        ["I heard that the tall man fears only strong winds."] = "Escuché que el hombre alto solo teme a los vientos fuertes.",
        ["In Canifis the men are known for eating much spam."] = "En Canifis los hombres son conocidos por comer mucho spam.",
        ["I am the egg man, are you one of the egg men?"] = "Yo soy el hombre huevo, ¿eres tú uno de los hombres huevo?",
        ["The sudden appearance of a deaf squirrel is most puzzling, comrade."] = "La repentina aparición de una ardilla sorda es de lo más desconcertante, camarada.",
        ["I believe that it is very rainy in Varrock."] = "Creo que llueve mucho en Varrock.",
        ["The slowest of fishermen catch the swiftest of fish."] = "Los pescadores más lentos capturan los peces más rápidos.",
        ["It is quite easy being green."] = "Es bastante fácil ser ecológico.",
        ["Don't forget to find the jade monkey."] = "No olvides encontrar el mono de jade.",
        ["I am the milkman. My milk is delicious."] = "Soy el lechero. Mi leche es deliciosa.",
        ["The brown cow flies at midnight."] = "La vaca marrón vuela a medianoche.",
        ["I wear the cheese; it does not wear me."] = "Yo uso el queso; no me desgasta.",
        ["How much hide would a hidey-hole hide if a hidey-hole could hide hide?"] = "¿Cuánta piel escondería un escondite si un escondite pudiera esconder?",
        ["*The player responds with*"] = "*el player responde con*",
        ["What?"] = "¿Qué?",
        ["You've found a scroll box!"] = "¡Has encontrado un cuadro de desplazamiento!",
        ["*When not following the instructions*"] = "*Cuando no se siguen las instrucciones*",
        ["I do not believe we have any business, comrade."] = "No creo que tengamos ningún negocio que hacer, camarada.",
        ["You've found a casket!"] = "¡Has encontrado un ataúd!",
    },
    ["Urist Loric"] = {
        ["The dwarf is hard at work on some sort of highly delicate construction, and doesn't pay you any notice."] = "El enano está trabajando duro en una especie de construcción muy delicada y no te hace caso.",
        ["Sorry laddie, I'm not taking commissions at the moment."] = "Lo siento muchacho, no aceptaré comisiones en este momento.",
        ["I've lost almost all my capital, so I'm just selling tools until I make enough to go back into the jewellery and clockwork business."] = "He perdido casi todo mi capital, así que solo vendo herramientas hasta que gane lo suficiente para volver al negocio de la joyería y la relojería.",
        ["Select an Option"] = "Selecciona una opción",
        ["Can I see what you have?"] = "¿Puedo ver lo que tienes?",
        ["Is that your talisman by your foot there?"] = "¿Es ese tu talismán que tienes ahí junto a tu pie?",
        ["Where?"] = "¿Dónde?",
        ["Yoink!"] = "¡Yoink!",
        ["[As he looks away you take the monocle from his top pocket.]"] = "[Mientras él mira hacia otro lado, sacas el monóculo de su bolsillo superior.]",
        ["I'm sorry to hear that."] = "Lamento oír eso.",
        ["Top of the morning. At least I think it's morning. <br>Can I interest you in some crafting supplies?"] = "Lo mejor de la mañana. Al menos creo que es de mañana. <br>¿Puedo interesarte en algunos materiales para manualidades?",
        ["I also have some gem stones for sale. Uncut, but don't ask me where I got them."] = "También tengo algunas piedras preciosas a la venta. Sin cortes, pero no me preguntes de dónde los saqué.",
        ["Where did you get the gemstones?"] = "¿De dónde sacaste las piedras preciosas?",
        ["I told you not to ask me that. <br>Let's just say I've made some friends in questionably legal places."] = "Te dije que no me preguntaras eso. <br>Digamos que he hecho algunos amigos en lugares cuestionablemente legales.",
        ["Does New Varrock ever get sunny?"] = "¿Alguna vez hace sol el nuevo Varrock?",
        ["Who needs daytime when it's always sunny in our hearts?"] = "¿Quién necesita el día cuando siempre hace sol en nuestros corazones?",
        ["Haha! Hahahahaha! <br>Who says zombies don't have a sense of humour?"] = "¡Jaja! ¡Jajajajaja! <br>¿Quién dice que los zombies no tienen sentido del humor?",
        ["No, thanks."] = "No, gracias.",
    },
    ["Urluk"] = {
        ["Hey, Hassan and the leaders were looking for you. Best you talk to them first."] = "Oye, Hassan y los líderes te estaban buscando. Será mejor que hables con ellos primero.",
        ["Complete the Jack of Spades quest to get access to Urluk."] = "Completa la misión Jack of Spades para obtener acceso a Urluk.",
        ["I try to give people help and directions around here."] = "Intento brindar ayuda e indicaciones a la gente por aquí.",
        ["People just make fun of me though."] = "Aunque la gente simplemente se burla de mí.",
        ["What are you talking about? Why would I make fun of you?"] = "¿De qué estás hablando? ¿Por qué me burlaría de ti?",
        ["Well if I told you that you would make fun of me..."] = "Bueno, si te dijera que te burlarías de mí...",
        ["Everyone always makes fun of me behind my back, but camels have brilliant hearing, you know?"] = "Todo el mundo siempre se burla de mí a mis espaldas, pero los camellos tienen un oído brillante, ¿sabes?",
        ["I think I'm starting to see the problem here, I'll get going."] = "Creo que estoy empezando a ver el problema aquí, continuaré.",
        ["No, wait! They make fun of me because I haven't moved in fifty human years. I just like to sit here and smoke cinchor."] = "¡No, espera! Se burlan de mí porque no me he movido en cincuenta años humanos. Sólo me gusta sentarme aquí y fumar cincho.",
        ["How have you kept yourself in food and water? I'm not even mad I'm impressed."] = "¿Cómo te has mantenido en comida y agua? Ni siquiera estoy enojado, estoy impresionado.",
        ["Not gonna lie; I store it in my humps. Haven't needed to eat for decades. You seem nice. Need any advice on what to do round here?"] = "No voy a mentir; Lo guardo en mis jorobas. No he necesitado comer durante décadas. Pareces agradable. ¿Necesitas algún consejo sobre qué hacer por aquí?",
        ["Choose an option: {{anchor"] = "Elige una opción: {{anchor",
        ["What can I do here?"] = "¿Qué puedo hacer aquí?",
        ["You should try cutting Acadia Trees. You will find them on the raised plateau in the Imperial District, ask a guard if you get lost!"] = "Deberías intentar cortar árboles de Acadia. Los encontrarás en la meseta elevada del Distrito Imperial, ¡pregúntale a un guardia si te pierdes!",
        ["This is a great way to grow your reputation with a faction of your choice."] = "Esta es una excelente manera de hacer crecer tu reputación con la facción que elijas.",
        ["You should try some Thieving in the market place next to us."] = "Deberías probar algo de Thieving en el mercado junto a nosotros.",
        ["You might find that you earn reputation for doing so."] = "Es posible que ganes reputación por hacerlo.",
        ["You should try fishing some Beltfish in the ports district."] = "Deberías intentar pescar algunos Beltfish en el distrito portuario.",
        ["You should go hunt some Plover Birds across the river in Sophanem."] = "Deberías ir a cazar algunos chorlitos al otro lado del río en Sophanem.",
        ["You should do some Shifting Tombs in any of the four districts. Look for the spire."] = "Deberías hacer algunas Tumbas Móviles en cualquiera de los cuatro distritos. Busque la aguja.",
        ["Someone around the city was looking for help. I can't remember the name... [NPC] maybe?"] = "Alguien en la ciudad estaba buscando ayuda. No recuerdo el nombre... ¿[NPC] tal vez?",
        ["You should do one of the City Quests. Try a citizen in need to talk to."] = "Deberías realizar una de las misiones de la ciudad. Pruebe con un ciudadano que necesita hablar.",
        ["You should go do some Slayer in the Sophanem Slayer dungeon. Make sure to pick up some feathers of Ma'at from the general store."] = "Deberías ir a hacer algo de Slayer en la mazmorra Sophanem Slayer. Asegúrate de recoger algunas plumas de Ma'at del general store.",
        ["You should go do some Divination in Sophanem, look for the Luminous Wisps near the river."] = "Deberías hacer algo de Divination en Sophanem, busca los Luminous Wisps cerca del río.",
        ["You should try training your Crafting on the spinning wheel in the Port district."] = "Deberías intentar entrenar a tu Crafting en la rueca en el distrito portuario.",
        ["You should try training your Smithing on the furnace and anvil in the Worker or Port districts."] = "Deberías intentar entrenar a tu Smithing en el horno y el yunque en los distritos de trabajadores o portuarios.",
        ["You should try training your Cooking or Firemaking on the fire pit in the Worker's district."] = "Deberías intentar entrenar tu Cooking o Firemaking en la fogata del Distrito de los Trabajadores.",
        ["What should I aim for?"] = "¿A qué debo aspirar?",
        ["You could do a quest. You aren't well known enough round these parts to be eligible for one, however."] = "Podrías hacer una misión. Sin embargo, no eres lo suficientemente conocido en estos lugares como para ser elegible para uno.",
        ["Level 3 Reputation is required for 'Crocodile Tears'."] = "Se requiere reputación de nivel 3 para 'Crocodile Tears'.",
        ["I can't think of anything more right now, talk to me in a second!"] = "No se me ocurre nada más ahora, ¡háblame en un segundo!",
        ["You should go train your Hunter in order to catch plover birds."] = "Deberías ir a entrenar tu Hunter para atrapar pájaros chorlitos.",
        ["Level 72 Hunter required to catch plover birds."] = "Se requiere nivel 72 Hunter para capturar pájaros chorlitos.",
        ["You should train your Crafting to do Shifting Tombs."] = "Deberías entrenar a tu Crafting para que haga Shifting Tombs.",
        ["Level 50 Crafting required to do Shifting Tombs."] = "Se requiere nivel 50 Crafting para hacer Tumbas Móviles.",
        ["You could do a quest. The citizens of Nardah are undergoing a drought. That could be something to fix beforehand."] = "Podrías hacer una misión. Los ciudadanos de Nardah están sufriendo una sequía. Eso podría ser algo que arreglar de antemano.",
        ["Completion of Spirits of the Elid is required for Crocodile Tears."] = "Es necesario completar Spirits of the Elid para Crocodile Tears.",
        ["You need to improve your slaying to get into the Sophanem Slayer Dungeon."] = "Necesitas mejorar tu habilidad para matar para ingresar a la mazmorra Sophanem Slayer.",
        ["88 Slayer is required for the Sophanem Slayer dungeon."] = "Se requiere 88 Slayer para la mazmorra Sophanem Slayer.",
        ["You should improve your divining ability to utilise the colony in Sophanem."] = "Deberías mejorar tu habilidad de adivinación para utilizar la colonia en Sophanem.",
        ["90 Divination is required to harvest the Sophanem luminous wisp colony."] = "Se requieren 90 Divination para cosechar la colonia de mechones luminosos Sophanem.",
        ["**Urluk:{{anchor|more-things}}** Hmm, well, here's a few more things you could aim for...but I'll let you discover them yourself."] = "**Urluk:{{anchor|more-things}}** Hmm, bueno, aquí hay algunas cosas más a las que podrías aspirar... pero dejaré que las descubras tú mismo.",
        ["Oh! You've done a LOT of things in Menaphos. This deserves a greater reward than a mere cape of the palapa!"] = "¡Oh! Has hecho MUCHAS cosas en Menaphos. ¡Esto merece una recompensa mayor que una simple capa de palapa!",
        ["You have unlocked the '{{Coloury}}' title!|colour=#AAC371}}"] = "¡Has desbloqueado el título '{{Coloury}}'!|color=#AAC371}}",
        ["You have unlocked the '{{Coloury}}' title!|colour=#AAC371|shadow=no}}"] = "¡Has desbloqueado el título '{{Coloury}}'!|color=#AAC371|shadow=no}}",
        ["You know what? I think you're all good."] = "¿Sabes qué? Creo que estáis todos bien.",
        ["Can I get your cape?"] = "¿Puedo conseguir tu capa?",
        ["The Cape of the Palapa is only for those who have seen the world."] = "El Cabo de la Palapa es sólo para aquellos que han visto mundo.",
        ["Do a Shifting Tomb as well as trying out the Woodcutting, Thieving, Mining, Fishing and Hunter in Menaphos and Sophanem to recieve{{Sic}} the cape."] = "Haz una tumba móvil y prueba Woodcutting, Thieving, Mining, Fishing y Hunter en Menaphos y Sophanem para recibir la capa {{Sic}}.",
        ["Congratulations! You have completed: 'Jack of all Menaphos' - Do a bit of everything in Menaphos and claim the cape of the palapa from Urluk."] = "¡Felicitaciones! Has completado: 'Jack of all Menaphos' - Haz un poco de todo en Menaphos y reclama la capa de la palapa de Urluk.",
        ["You have unlocked the cape of the palapa!"] = "¡Has desbloqueado la capa de la palapa!",
        ["Made out of braided cloth strands. You'll never feel exposed again."] = "Hecho de hilos de tela trenzados. Nunca más te sentirás expuesto.",
        ["Do you have any rumours about City Quests?"] = "¿Tienes algún rumor sobre City Quests?",
        ["Someone around the city was looking for help. I can't remember the name.... [NPC] maybe?"] = "Alguien en la ciudad estaba buscando ayuda. No recuerdo el nombre.... ¿[NPC] tal vez?",
        ["You should do one of the city Quests. From time to time a citizen will need help, I guarantee it."] = "Deberías hacer una de las misiones de la ciudad. De vez en cuando un ciudadano necesitará ayuda, lo garantizo.",
        ["How can I understand you?"] = "¿Cómo puedo entenderte?",
        ["During my travels, I found an amulet of humanspeak. I have to say it has come in very handy in stopping you lot from attacking me."] = "Durante mis viajes, encontré un amuleto de habla humana. Debo decir que ha sido muy útil para evitar que me ataquen.",
    },
    ["Usi"] = {
        ["Good day to you."] = "Buenos días para ti.",
        ["It's not that good, it's a bit warm."] = "No está tan bueno, hace un poco de calor.",
        ["The curse has been removed. Word around the town is that you were the one who helped remove it."] = "La maldición ha sido eliminada. Se dice en la ciudad que tú fuiste quien ayudó a eliminarlo.",
        ["Yes that is correct. The spirits of the Elid cursed the town for throwing away a statue to Elidinis. I got it"] = "Sí, eso es correcto. Los espíritus de los Elid maldijeron a la ciudad por arrojar una estatua a Elidinis. lo tengo",
        ["Well we thank you. You’re pretty much a local hero now."] = "Bueno, te lo agradecemos. Ahora eres prácticamente un héroe local.",
    },
    ["Utu"] = {
        ["A divine wolf pup stares up at you. His expression is a mixture of curiosity and apprehension."] = "Un cachorro de lobo divino te mira fijamente. Su expresión es una mezcla de curiosidad y aprensión.",
        ["Hello there, little one."] = "Hola, pequeña.",
        ["Hello there."] = "Hola.",
        ["Are you alright? Who are you?"] = "¿Estás bien? ¿Quién eres?",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Player. Do you know your name?"] = "Soy Player. ¿Sabes tu nombre?",
        ["Know your...name. Yes."] = "Conoce tu... nombre. Sí.",
        ["Utu. I am Utu."] = "Utu. Soy Utu.",
        ["What are you doing here, Utu?"] = "¿Qué haces aquí, Utu?",
        ["What are you doing here, Player?"] = "¿Qué haces aquí, Player?",
        ["I was hoping I could explore the history of this temple."] = "Esperaba poder explorar la historia de este templo.",
        ["This temple...I protect this temple. It was my duty. It is my duty."] = "Este templo... Yo protejo este templo. Era mi deber. Es mi deber.",
        ["Do you remember anything, aside from your name and your duty?"] = "¿Recuerdas algo, aparte de tu nombre y tu deber?",
        ["My memories have flittered away, like autumn leaves on the wind. I am barren in their absence."] = "Mis recuerdos se han ido volando, como hojas de otoño en el viento. Soy estéril en su ausencia.",
        ["I could excavate the temple. See what I can find. Maybe I'll come across something that will help restore your memories."] = "Podría excavar el templo. A ver que puedo encontrar. Tal vez encuentre algo que le ayude a restaurar sus recuerdos.",
        ["Very well. It shall be your duty. Explore the history of the temple. Help me restore my memories."] = "Muy bien. Será tu deber. Explora la historia del templo. Ayúdame a restaurar mis recuerdos.",
        ["I'll get started, then. Thank you, Utu."] = "Entonces empezaré. Gracias, Utu.",
        ["Thank you, Player."] = "Gracias, Player.",
        ["Hello, Player."] = "Hola, Player.",
        ["Greetings, little one."] = "Saludos, pequeña.",
        ["Select an Option"] = "Seleccione una opción",
        ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
        ["I remember little of myself. Of my past. This temple is all I know."] = "Recuerdo poco de mí. De mi pasado. Este templo es todo lo que conozco.",
        ["Have you ever been inside?"] = "¿Has estado alguna vez dentro?",
        ["No. When I approach its door a voice echoes across my mind. A warning. A command. To never enter the temple's depths."] = "No. Cuando me acerco a su puerta, una voz hace eco en mi mente. Una advertencia. Un comando. Nunca entrar en las profundidades del templo.",
        ["A voice in your head? Whose voice?"] = "¿Una voz en tu cabeza? ¿La voz de quién?",
        ["I do not know. But it is familiar."] = "No lo sé. Pero me resulta familiar.",
        ["Perhaps it is my own."] = "Quizás sea mío.",
        ["I woke before the Lunar Wheel many cycles ago, knowing naught but my name and my duty: to watch over this temple."] = "Me desperté ante la Rueda Lunar hace muchos ciclos, sin saber nada más que mi nombre y mi deber: velar por este templo.",
        ["In truth, it is more than duty that keeps me here. I am bound to this place. To its past. Its secrets. To the very stone into which it is carved."] = "En verdad, es más que el deber lo que me mantiene aquí. Estoy atado a este lugar. A su pasado. Sus secretos. A la misma piedra en la que está tallado.",
        ["What do you mean? You can't leave?"] = "¿Qué quieres decir? ¿No puedes irte?",
        ["Can the moon flee the sky, to walk with mortals upon the land?"] = "¿Puede la luna huir del cielo para caminar con los mortales sobre la tierra?",
        ["From the moment I awoke, an immeasurable sorrow has raged within my soul. Shame. Regret. Like a parasite, slowly consuming me from within."] = "Desde el momento en que desperté, un dolor inconmensurable ha arrasado mi alma. Lástima. Arrepentirse. Como un parásito, consumiéndome lentamente desde dentro.",
        ["I must know its cause. Until my memories have been restored, I will never know peace."] = "Debo saber su causa. Hasta que mis recuerdos no sean restaurados, nunca conoceré la paz.",
        ["You may not like what you learn."] = "Puede que no te guste lo que aprendes.",
        ["**Utu: ** So be it. No knowledge could cause such suffering as this."] = "**Utu: ** Que así sea. Ningún conocimiento podría causar tal sufrimiento.",
        ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
        ["This place stirs many feelings. Hollowness. Shame. Disgrace."] = "Este lugar despierta muchos sentimientos. Hueco. Lástima. Desgracia.",
        ["Why's that?"] = "¿Por qué?",
        ["I do not know. Perhaps I did, once."] = "No lo sé. Quizás lo hice, alguna vez.",
        ["It is lonely, standing watch over this temple. Two humans visited before you. One your size. One nearer mine. I had only recently awoken. I dared not reveal myself to them."] = "Es muy solitario estar vigilando este templo. Dos humanos te visitaron antes. Uno de tu talla. Uno más cerca del mío. Me había despertado recientemente. No me atrevía a revelarme a ellos.",
        ["I has been less lonely, since meeting you."] = "Me he sentido menos solo desde que te conocí.",
        ["I'm glad to hear that."] = "Me alegra oír eso.",
        ["This is the great temple of Akshur-Nakkir. Jewel of the Nakkirian people. Seat of the divine."] = "Este es el gran templo de Akshur-Nakkir. Joya del pueblo Nakkirian. Asiento de lo divino.",
        ["We were as gods to the people who lived here. They came to us with offerings and worship. We granted them our blessings in return."] = "Éramos como dioses para la gente que vivía aquí. Vinieron a nosotros con ofrendas y adoración. A cambio, les concedimos nuestras bendiciones.",
        ["Those who live here now call this place 'Moonrise'."] = "Quienes viven aquí ahora llaman a este lugar 'Salida de la Luna'.",
        ["An apt name, for we held the moon in high regard."] = "Un nombre apropiado, porque teníamos en alta estima a la luna.",
        ["The Lunar Wheel was a gift from Guthix, the slumbering god, himself. Carved by his own hands when he shaped this world. I cannot recall the true extent of its power."] = "La Rueda Lunar fue un regalo del propio Guthix, el dios dormido. Tallado por sus propias manos cuando dio forma a este mundo. No puedo recordar el verdadero alcance de su poder.",
        ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
        ["Bye."] = "Adiós.",
        ["Farewell, Player."] = "Adiós, Player.",
        ["Moonlight guide your path."] = "La luz de la luna guía tu camino.",
        ["How are you feeling, Utu?"] = "¿Cómo te sientes, Utu?",
        ["The revelations you have uncovered are a lot to take in. There is much to reflect on. Much to ponder."] = "Las revelaciones que has descubierto son mucho para asimilar. Hay mucho sobre lo que reflexionar. Mucho para reflexionar.",
        ["I require time. Please, Player, {{Sic|Leave}} me to my thoughts."] = "Necesito tiempo. Por favor, Player, {{Sic|Leave}}, déjame ir a mis pensamientos.",
        ["Very well."] = "Muy bien.",
        ["I haven't found any clues to your past yet, but I'm making progress."] = "Aún no he encontrado ninguna pista sobre tu pasado, pero estoy progresando.",
        ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
        ["Shadows of the Colossi."] = "Sombras de los colosos.",
        ["Path of the Initiate"] = "Camino del Iniciado",
        ["Cult Classic."] = "Clásico de culto.",
        ["Inside You There Are Two Wolves."] = "Dentro de ti hay dos lobos.",
    },
}

dialogues.all = {
    ["Hello there. Could I ask you about the-"] = "Hola. ¿Puedo preguntarte sobre-?",
    ["Not at the moment, I'm afraid! It's not nearly safe enough to talk right now."] = "¡Me temo que no por el momento! No es lo suficientemente seguro hablar ahora.",
    ["But you don't even know what I was going to ask!"] = "¡Pero ni siquiera sabes lo que iba a preguntar!",
    ["Oh, I have enough of an idea to know that it's not safe enough to talk about it on a free world."] = "Oh, tengo una idea suficiente para saber que no es lo suficientemente seguro hablar de ello en un mundo libre.",
    ["Hi there. What are you doing here?"] = "Hola. ¿Qué estás haciendo aquí?",
    ["I'm afraid that I don't have much time to chat right now."] = "Me temo que no tengo mucho tiempo para charlar en este momento.",
    ["Really? You don't seem to be doing anything but standing around."] = "¿En serio? Parece que no estás haciendo nada más que quedarte parado.",
    ["Well, that's where your eyes deceive you! I'm not only standing around, I'm also scanning the horizon. It takes a lot of energy and concentration to remain prepared for emergencies."] = "Bueno, ¡ahí es donde tus ojos te engañan! No sólo estoy parado, sino que también escudriño el horizonte. Se necesita mucha energía y concentración para estar preparado para las emergencias.",
    ["I see."] = "Ya veo.",
    ["Hello, traveller! Could I impose on you for a moment?"] = "¡Hola viajero! ¿Puedo imponerte por un momento?",
    ["What is it?"] = "¿Qué es?",
    ["Well, I'm supposed to be looking after these beacons, but I'm utterly exhausted. Constantly scanning the horizon is hard work."] = "Bueno, se supone que debo cuidar estas balizas, pero estoy completamente agotado. Escudriñar constantemente el horizonte es un trabajo duro.",
    ["I've heard that the fruit from the White Tree can pep one up a bit. Is there any way you could bring me one? I'd be eternally grateful."] = "He oído que la fruta del Árbol Blanco puede animarnos un poco. ¿Hay alguna manera de que puedas traerme uno? Estaría eternamente agradecido.",
    ["Select an Option"] = "Seleccione una opción",
    ["I'd be happy to help."] = "Estaré feliz de poder ayudar.",
    ["I'd be happy to help. The safety of the kingdom is paramount, after all."] = "Estaré encantado de ayudarte. Después de todo, la seguridad del reino es primordial.",
    ["Thank you very much. I'm worried that if I carry on on this state, I might miss something important."] = "Muchas gracias. Me preocupa que si sigo en este estado, podría perderme algo importante.",
    ["Sorry, I'm busy at the moment."] = "Lo siento, estoy ocupado en este momento.",
    ["Ah, well. It costs nothing to ask."] = "Ah, bueno. No cuesta nada preguntar.",
    ["Hello, traveller! Look, I hate to be rude, but is that the aroma of White Tree fruit I smell?"] = "¡Hola viajero! Mira, odio ser grosero, pero ¿es ese el aroma de la fruta del Árbol Blanco lo que huelo?",
    ["It might be."] = "Puede que lo sea.",
    ["You wouldn't happen to have one on you going spare, would you? I'm utterly exhausted and could really use a pick-me-up."] = "No tendrás uno de repuesto, ¿verdad? Estoy completamente exhausto y me vendría bien un estímulo.",
    ["Of course; I brought one just for you."] = "Por supuesto; Traje uno solo para ti.",
    ["Thank you ever so much. I can't tell you how much I was craving White Tree fruit."] = "Muchas gracias. No puedo decirte cuánto ansiaba la fruta del Árbol Blanco.",
    ["Glad to help."] = "Encantado de poder ayudar.",
    ["Should I ever be able to repay the favour, just let me know."] = "Si algún día puedo devolverte el favor, házmelo saber.",
    ["Sorry, I can't help you right now."] = "Lo siento, no puedo ayudarte en este momento.",
    ["Hello. Can I help you at all?"] = "Hola. ¿Puedo ayudarte en algo?",
    ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
    ["Of course. Once the beacon is lit, just leave 5 logs with me and I'll take care of the fire for as long as I can."] = "Por supuesto. Una vez que la baliza esté encendida, déjame 5 logs y yo me ocuparé del fuego todo el tiempo que pueda.",
    ["Well, I could, but since you're here, you might as well do it yourself."] = "Bueno, podría, pero ya que estás aquí, es mejor que lo hagas tú mismo.",
    ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
    ["I'm afraid you don't have enough of the right type of log for me to use."] = "Me temo que no tienes suficiente registro del tipo correcto para que yo lo use.",
    ["I'll need five logs to be able to tend the fire. Is that okay?"] = "Necesitaré cinco logs para poder atender el fuego. ¿Está bien?",
    ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
    ["Yes."] = "Sí.",
    ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
    ["Thank you! I'll use these five logs to keep the beacon burning while you're away."] = "¡Gracias! Usaré estos cinco logs para mantener encendida la baliza mientras estás fuera.",
    ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
    ["Well, you know where I am if you change your mind."] = "Bueno, ya sabes dónde estoy si cambias de opinión.",
    ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
    ["Of course I will, don't worry, I'll use the logs you've already left with me."] = "Por supuesto que lo haré, no te preocupes, usaré el logs que ya me dejaste.",
    ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
    ["But of course. Just have a look at my map."] = "Pero claro. Sólo echa un vistazo a mi mapa.",
    ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
    ["I can tell you about the state of the beacons in either direction, up to the last fires that are lit."] = "Puedo informarte del estado de las balizas en ambas direcciones, hasta los últimos fuegos que se encienden.",
    ["I could probably tell you about the other beacons as well, but I'd need the help of a macaw."] = "Probablemente también podría contarte sobre las otras balizas, pero necesitaría la ayuda de una guacamaya.",
    ["A macaw?"] = "¿Una guacamaya?",
    ["Yes. Macaws have the ability to fly high into the air and see things that are much further away."] = "Sí. Los guacamayos tienen la capacidad de volar muy alto en el aire y ver cosas que están mucho más lejos.",
    ["They are also highly intelligent and can be trained to provide the exact information I'd need for a complete overview of the beacon network."] = "También son muy inteligentes y se les puede entrenar para proporcionar la información exacta que necesito para obtener una descripción completa de la red de balizas.",
    ["Come to think of it, the macaw you've got there in your pack would be perfect."] = "Ahora que lo pienso, la guacamaya que tienes en tu mochila sería perfecta.",
    ["How's it going?"] = "¿Cómo te va?",
    ["Pretty good, for the most part. I've done quite a lot of looking at the horizon today - it's quite hard work."] = "Bastante bien, en su mayor parte. He mirado mucho el horizonte hoy; es un trabajo bastante duro.",
    ["Have you seen anything worrying?"] = "¿Has visto algo preocupante?",
    ["Not so far, thankfully, but one has to stay constantly vigilant for threats coming from the north."] = "No hasta ahora, afortunadamente, pero hay que estar constantemente atento a las amenazas que vienen del norte.",
    ["Isn't it exhausting, constantly keeping your eyes peeled like that?"] = "¿No es agotador tener los ojos bien abiertos constantemente?",
    ["Well, actually, staring intently at anything for too long can be a strain on one's eyes."] = "Bueno, en realidad, mirar fijamente algo durante demasiado tiempo puede resultar agotador para la vista.",
    ["I take a little break every hour or so and look away from the horizon for a few minutes, just to rest my eyes."] = "Tomo un pequeño descanso aproximadamente cada hora y aparto la vista del horizonte durante unos minutos, sólo para descansar la vista.",
    ["Oh? What do you look at, then?"] = "¿Ah? ¿Qué miras entonces?",
    ["Well, actually, I'm also using this opportunity to increase my knowledge about local moulds and fungi."] = "Bueno, en realidad, también estoy aprovechando esta oportunidad para aumentar mis conocimientos sobre mohos y hongos locales.",
    ["Are you being serious?"] = "¿Hablas en serio?",
    ["Not only can I spot danger from miles away, but I'm the quickest identifier of bread moulds this side of the River Lum!"] = "¡No solo puedo detectar el peligro a kilómetros de distancia, sino que soy el identificador más rápido de moho en el pan de este lado del río Lum!",
    ["That's a...unique claim to fame."] = "Ese es... un reclamo único a la fama.",
    ["I'm quite proud of it, really. I'm hoping to branch out to yeasts next, then mushrooms."] = "Estoy muy orgulloso de ello, de verdad. Espero expandirme a las levaduras y luego a los champiñones.",
    ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
    ["Fine! I'm done talking to you, too, then."] = "¡Bien! Entonces ya terminé de hablar contigo.",
    ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
    ["Thank you very much. This macaw will help me give you more detailed information about the beacon network."] = "Muchas gracias. Esta guacamaya me ayudará a brindarles información más detallada sobre la red de balizas.",
    ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["I've already given her a macaw; she doesn't need another."] = "Ya le regalé una guacamaya; ella no necesita otra.",
    ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
    ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
    ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
    ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
    ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
    ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
    ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
    ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    ["Hey, what's going on here?"] = "Oye, ¿qué está pasando aquí?",
    ["Dem's dead ogre's come out of the ground...dey's makin' da rest of us into sick-ums ...and dead-uns."] = "El ogro muerto de Dem ha salido de la tierra... están convirtiendo al resto de nosotros en enfermos... y muertos.",
    ["That doesn't sound good!"] = "¡Eso no suena bien!",
    ["Grish want's da person go down der - see what's what!"] = "Grish quiere que la persona baje, ¡mira qué es qué!",
    ["What are you selling?"] = "¿Qué estás vendiendo?",
    ["Me's not got no glug-glugs to sell, yous bring me da sickies glug-glug den me's open da stufsies for ya."] = "No tengo glug-glugs para vender, tráeme los enfermos glug-glug y te abriré las cosas.",
    ["Ok, thanks."] = "Vale, gracias.",
    ["Hello again."] = "Hola de nuevo.",
    ["Hey yous creature... yous did good fings gedin that glug-glugs for da sickies! All is ogries pepels are not gettin dead cos of you."] = "Oye, criatura... ¡Hiciste buenos dedos con ese glug-glugs para los enfermos! Todo son ogros y los pepels no van a morir por tu culpa.",
    ["Me's showin' you da stufsies for yous creatures!"] = "¡Yo les estoy mostrando cosas para sus criaturas!",
    ["You wants the puzzles?"] = "¿Quieres los rompecabezas?",
    ["[Uglug Nar has given you a puzzle box!]"] = "[¡Uglug Nar te ha regalado una caja de rompecabezas!]",
    ["Dat's not done yet!"] = "¡Eso aún no ha terminado!",
    ["[Uglug Nar has given you another clue scroll!]"] = "[¡Uglug Nar te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Dere you go!"] = "¡Aquí vas!",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["Ask the camel about its dung."] = "Pregúntale al camello por su estiércol.",
    ["I'm sorry to bother you, but could you spare me a little dung?"] = "Lamento molestarte, pero ¿podrías ahorrarme un poco de estiércol?",
    ["The camel didn't seem to appreciate that question."] = "El camello no pareció apreciar esa pregunta.",
    ["Say something unpleasant."] = "Di algo desagradable.",
    ["*Player may say any one of the following at random:*"] = "*Player puede decir cualquiera de las siguientes palabras al azar:*",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["Mmm... Looks like that camel would make a nice kebab."] = "Mmm... Parece que ese camello sería un buen kebab.",
    ["*(Continues below)*"] = "*(Continúa a continuación)*",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["I wonder if that camel has fleas..."] = "Me pregunto si ese camello tendrá pulgas...",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["If I go near that camel, it'll probably bite my hand off."] = "Si me acerco a ese camello, probablemente me arrancará la mano de un mordisco.",
    ["*Ugthanki may do any of the following at random:*"] = "*Ugthanki puede hacer cualquiera de las siguientes cosas al azar:*",
    ["*Response 1:*"] = "*Respuesta 1:*",
    ["The camel turns its head and glares at you."] = "El camello gira la cabeza y te mira fijamente.",
    ["*Response 2:*"] = "*Respuesta 2:*",
    ["The camel tries to stamp on your foot, but you pull it back quickly."] = "El camello intenta pisotearte el pie, pero lo retiras rápidamente.",
    ["*Response 3:*"] = "*Respuesta 3:*",
    ["The camel spits at you, and you jump back hurriedly."] = "El camello te escupe y saltas hacia atrás apresuradamente.",
    ["Neither - I'm a polite person."] = "Ninguno de los dos, soy una persona educada.",
    ["You decide not to be rude."] = "Decides no ser grosero.",
    ["Dung? How dare you?!"] = "¿Estiércol? ¡¿Cómo te atreves?!",
    ["*Ugthanki may say any one one of the following at random:*"] = "*Ugthanki puede decir cualquiera de las siguientes palabras al azar:*",
    ["Come over here, I'll bite your leg off!"] = "¡Ven aquí, te arrancaré la pierna de un mordisco!",
    ["Prepare to die, you two-legged combat wrangler!"] = "¡Prepárate para morir, luchador de combate de dos piernas!",
    ["Your mother was a jackal, and your father smelt of cactus!"] = "¡Tu madre era un chacal y tu padre olía a cactus!",
    ["Say, aren't you the human who got arrested here the other day, by the boat?"] = "Dime, ¿no eres tú el humano que fue arrestado aquí el otro día, junto al barco?",
    ["Yes, but we cleared up the whole situation."] = "Sí, pero aclaramos toda la situación.",
    ["Right, right."] = "Bien, bien.",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after A [animal]"] = "También estoy buscando un nuevo animal, actualmente estoy buscando A [animal]",
    ["If you complete this, I'll give you : Ring of forging x 5. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Anillo de forja x 5. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [número] horas y [número] minutos. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
    ["[You've received : Ring of forging x 5<br>And 2,750 farming reputation.]"] = "[Has recibido: Anillo de forja x 5<br>Y 2750 de reputación agrícola.]",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["A new request will be available in [time].."] = "Una nueva solicitud estará disponible en [time].",
    ["You've already completed this request, there will be a new daily request in [time].."] = "Ya has completado esta solicitud, habrá una nueva solicitud diaria en [time].",
    ["Hello there."] = "Hola.",
    ["What... Oh, don't creep up on me like that... I thought you were a Ghast!"] = "Qué... Oh, no te acerques así... ¡Pensé que eras un Ghast!",
    ["Can I go through the gate please?"] = "¿Puedo pasar por la puerta, por favor?",
    ["Absolutely not! I've been given strict instructions not to let anyone through. It's just too dangerous. No one gets in without Drezels say so!"] = "¡Por supuesto que no! Me han dado instrucciones estrictas de no dejar pasar a nadie. Es demasiado peligroso. ¡Nadie entra sin que Drezels lo diga!",
    ["Where is Drezel?"] = "¿Dónde está Drezel?",
    ["Oh, he's in the temple, just go back over the bridge, down the ladder and along the hallway, you can't miss him."] = "Oh, está en el templo, simplemente cruza el puente, baja la escalera y recorre el pasillo, no te lo puedes perder.",
    ["Yes of course my friend, you seem to be able to handle yourself with those ghasts really well."] = "Sí, por supuesto, amigo mío, parece que eres capaz de manejarte muy bien con esos fantasmas.",
    ["Very well done! Here you go!"] = "¡Muy bien hecho! ¡Aquí tienes!",
    ["[Ulizius has given you another clue scroll!]"] = "[¡Ulizius te ha dado otro pergamino de pistas!]",
    ["Hello. I'm Ulric, a Travelling Artisan, and this is my Mental Health Awareness event!"] = "Hola. Soy Ulric, un Artisan ambulante, ¡y este es mi evento de concientización sobre la salud mental!",
    ["During this event, there are plenty of unique rewards to be crafted."] = "Durante este evento, se pueden crear muchas recompensas únicas.",
    ["You gather the resources, and I'll do the crafting!"] = "¡Tú reúnes los recursos y yo haré la elaboración!",
    ["With each recipe crafted, I'll gain experience."] = "Con cada receta elaborada, ganaré experiencia.",
    ["Experience allows me to level up, which allows me to craft better recipes for you!"] = "¡La experiencia me permite subir de nivel, lo que me permite crear mejores recetas para ti!",
    ["Everyone's a winner!"] = "¡Todos somos ganadores!",
    ["Additionally, I've invited representatives from the CPSL Mind, Rise Above The Disorder, and the Prince's Trust charities to come along for its duration."] = "Además, he invitado a representantes de las organizaciones benéficas CPSL Mind, Rise Above The Disorder y Prince's Trust a que nos acompañen durante su duración.",
    ["Be sure to chat with them every 2 days, as they'll each have a new question to ask you."] = "Asegúrate de chatear con ellos cada 2 días, ya que cada uno tendrá una nueva pregunta que hacerte.",
    ["Each question answered correctly will bag you a Small prismatic lamp, and 100 Travelling Artisan Patches."] = "Cada pregunta respondida correctamente le otorgará una lámpara prismática pequeña y 100 parches Artisan itinerantes.",
    ["Great, thanks for the information!"] = "Genial, ¡gracias por la información!",
    ["Hey!"] = "¡Oye!",
    ["Hello. How can I help you?"] = "Hola. ¿Le puedo ayudar en algo?",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["How does this event work?"] = "¿Cómo funciona este evento?",
    ["Could you explain how this event works?"] = "¿Podrías explicar cómo funciona este evento?",
    ["**Ulric** Of course!"] = "**Ulric** ¡Por supuesto!",
    ["Why are the charity representatives here?"] = "¿Por qué están aquí los representantes de la caridad?",
    ["So why are the charity representatives here?"] = "Entonces, ¿por qué están aquí los representantes de la organización benéfica?",
    ["**Ulric** I'm glad you asked!"] = "**Ulric** ¡Me alegra que lo hayas preguntado!",
    ["**Ulric** This event coincides with World Mental Health Day."] = "**Ulric** Este evento coincide con el Día Mundial de la Salud Mental.",
    ["**Ulric** Therefore, I invited representatives from the CPSL Mind, Rise Above The Disorder, and the Prince's Trust charities to come along for its duration."] = "**Ulric** Por lo tanto, invité a representantes de CPSL Mind, Rise Above The Disorder y las organizaciones benéficas Prince's Trust a que nos acompañaran durante su duración.",
    ["That sounds great!"] = "¡Eso suena genial!",
    ["Goodbye."] = "Adiós.",
    ["Goodbye!"] = "¡Adiós!",
    ["Bye for now."] = "Adiós por ahora.",
    ["Yarr ye dare be fightin me! Do ye not know who I be? {{Audio button|Ulthven Keith - Yarr ye dare be fightin me.ogg}}"] = "¡Yarr, te atreves a pelear conmigo! ¿No sabes quién soy? {{Audio button|Ulthven Keith - Yarr ye dare be fightin me.ogg}}",
    ["I be Ulthven Keith, scourge o'the oceans and terror o'the seas. {{Audio button|Ulthven Keith - I be Ulthven Keith.ogg}}"] = "Seré Ulthven Keith, azote de los océanos y terror de los mares. {{Audio button|Ulthven Keith - I be Ulthven Keith.ogg}}",
    ["Even drowning hasn't stopped me from plundering the world! {{Audio button|Ulthven Keith - Even drowning hasn't stopped me.ogg}}"] = "¡Ni siquiera ahogarme me ha impedido saquear el mundo! {{Audio button|Ulthven Keith - Even drowning hasn't stopped me.ogg}}",
    ["Do you really think you be standing a chance against me blade? {{Audio button|Ulthven Keith - Do you really think you be standing.ogg}}"] = "¿De verdad crees que tienes alguna posibilidad contra mi espada? {{Audio button|Ulthven Keith - Do you really think you be standing.ogg}}",
    ["*Each fulfilled requirement will be striked off.*"] = "*Cada requisito cumplido será eliminado.*",
    ["Sorry, no time to talk."] = "Lo siento, no hay tiempo para hablar.",
    ["Hi Unferth. How's Bob?"] = "Hola Unferth. ¿Cómo está Bob?",
    ["I don't see him as much as I used to but he's fine."] = "Ya no lo veo tanto como antes, pero está bien.",
    ["Feeling OK?"] = "¿Te sientes bien?",
    ["Well my spleen is playing up again..."] = "Bueno, mi bazo está jugando otra vez...",
    ["I must go, something came up!"] = "¡Debo irme, surgió algo!",
    ["Oh, OK."] = "Oh, está bien.",
    ["An unstable soul appears nearby."] = "Un alma inestable aparece cerca.",
    ["Your focus stabilises the soul."] = "Tu enfoque estabiliza el alma.",
    ["The unstable soul disappears before you could guide it onwards."] = "El alma inestable desaparece antes de que puedas guiarla hacia adelante.",
    ["As you guide the unstable soul to the underworld, they thank you by sharing some of their [Skill] knowledge."] = "Mientras guías al alma inestable al inframundo, te lo agradecen compartiendo algunos de sus conocimientos [Skill].",
    ["You gain [number] [Skill] XP."] = "Obtienes [número] [Skill] XP.",
    ["The lost soul disappears before you could guide it onwards."] = "El alma perdida desaparece antes de que puedas guiarla hacia adelante.",
    ["At the next council meeting, I'm going to recommend that we change the guards uniforms to be red."] = "En la próxima reunión del consejo, voy a recomendar que cambiemos los uniformes de los guardias para que sean rojos.",
    ["Why?"] = "¿Por qué?",
    ["We have surface-dwellers coming down into our mines and our city now, and remember that they don't have very good eyesight. I worry that they can't see our guards very clearly in the dark. It is important for a guard to be seen."] = "Ahora tenemos habitantes de la superficie que bajan a nuestras minas y a nuestra ciudad, y recuerden que no tienen muy buena vista. Me preocupa que no puedan ver a nuestros guardias con mucha claridad en la oscuridad. Es importante que se vea a un guardia.",
    ["You have a point. But i don't think red would be the best colour. It's the colour of blood, so it might give the wrong impression."] = "Tienes razón. Pero no creo que el rojo sea el mejor color. Es el color de la sangre, por lo que podría dar una impresión equivocada.",
    ["What colour do you suggest, then?"] = "¿Qué color sugieres entonces?",
    ["I suggest green. I have heard that the plants that grow on the surface are mostly green, so surface-dwellers might find that colour soothing."] = "Sugiero verde. He oído que las plantas que crecen en la superficie son en su mayoría verdes, por lo que los habitantes de la superficie pueden encontrar ese color relajante.",
    ["No, I disagree. Guards should not be soothing, they should be seen as formidable. Red will give the correct impression."] = "No, no estoy de acuerdo. Los guardias no deben ser tranquilizadores, sino que deben ser vistos como formidables. El rojo dará la impresión correcta.",
    ["Oh, hello surface-dweller. We were just discussing some council business."] = "Oh, hola habitante de la superficie. Estábamos discutiendo algunos asuntos del consejo.",
    ["Do you want me to pick an armour colour for you?"] = "¿Quieres que elija un color de armadura para ti?",
    ["No, thank you. We don't one single goblin make decisions, and certainly not an outsider!"] = "No, gracias. No somos un solo duende el que toma decisiones, ¡y menos aún un extraño!",
    ["But we could do with an opinion. What armour colour do you think is best?"] = "Pero nos vendría bien una opinión. ¿Qué color de armadura crees que es mejor?",
    ["Red."] = "Rojo.",
    ["Thank you, surface-dweller. That's what I'll be recommending in the next meeting."] = "Gracias, habitante de la superficie. Eso es lo que recomendaré en la próxima reunión.",
    ["Green."] = "Verde.",
    ["I think the guards are fine as they are."] = "Creo que los guardias están bien tal como están.",
    ["Perhaps you're right. Not making any change would certainly be the easiest option!"] = "Quizás tengas razón. ¡No hacer ningún cambio sería sin duda la opción más fácil!",
    ["I think I've been here before..."] = "Creo que ya he estado aquí antes...",
    ["Oh? How so?"] = "¿Ah? ¿Cómo es eso?",
    ["This is a lot like a conversation I had with some goblins on the surface."] = "Esto se parece mucho a una conversación que tuve con algunos duendes en la superficie.",
    ["Really? Which armour colour did they pick?"] = "¿En serio? ¿Qué color de armadura eligieron?",
    ["They ended up with the same armour colour that they started with!"] = "¡Terminaron con el mismo color de armadura con el que empezaron!",
    ["You know, I think that's probably what we'll end up doing."] = "Sabes, creo que eso es probablemente lo que terminaremos haciendo.",
    ["*When speaking to Ur-Meg in Dorgesh-kaan*"] = "*Al hablar con Ur-Meg en Dorgesh-kaan*",
    ["Oh dear..."] = "Dios mío...",
    ["What's the matter?"] = "¿Qué pasa?",
    ["I'm worried. I think the Council is neglecting a big issue. I tried to bring it up at the last meeting, but they didn't pay attention."] = "Estoy preocupado. Creo que el Consejo está descuidando una cuestión importante. Intenté sacar el tema en la última reunión, pero no me prestaron atención.",
    ["What issue?"] = "¿Qué problema?",
    ["I'm very happy for you humans to come down to the city, but what about...them?"] = "Estoy muy feliz de que ustedes, los humanos, vengan a la ciudad, pero ¿qué pasa con... ellos?",
    ["What about who?"] = "¿Y quién?",
    ["Them! *whispers* The G-O-D-S."] = "¡Ellos! *susurra* Los DIOSES.",
    ["The gods?"] = "¿Los dioses?",
    ["Don't say it! What if they hear?"] = "¡No lo digas! ¿Qué pasa si escuchan?",
    ["Select an option"] = "Seleccione una opción",
    ["Why are you scared of the gods?"] = "¿Por qué tienes miedo de los dioses?",
    ["Because they're so powerful, of course! In the time of the great war, they forced all the goblin tribes to fight one another. Our ancestors weren't powerful enough to stand up to them. We've hidden down here for this long, but now the way to the surface is open, what if they find us again?"] = "¡Porque son muy poderosos, por supuesto! En la época de la gran guerra, obligaron a todas las tribus de duendes a luchar entre sí. Nuestros antepasados ​​no eran lo suficientemente poderosos para hacerles frente. Nos hemos escondido aquí durante tanto tiempo, pero ahora el camino a la superficie está abierto, ¿y si nos encuentran de nuevo?",
    ["You don't need to worry!"] = "¡No necesitas preocuparte!",
    ["I don't?"] = "¿No?",
    ["The god wars are over! The gods don't intervene directly in the affairs of mortals any more."] = "¡Las guerras de dioses han terminado! Los dioses ya no intervienen directamente en los asuntos de los mortales.",
    ["Are you sure?"] = "¿Estás seguro?",
    ["Yes!"] = "¡Sí!",
    ["I do hope you're right! I still can't help being worried, though."] = "¡Espero que tengas razón! Aunque todavía no puedo evitar preocuparme.",
    ["Don't you want to worship the god of the goblins?"] = "¿No quieres adorar al dios de los duendes?",
    ["No! How could you even suggest that? We're not going to worship some supernatural being just because it's bigger and more powerful than us. It may seem to you that we're cowardly, hiding here from the gods all this time, but I know that every Dorgeshuun would rather die than submit to the rule of any god."] = "¡No! ¿Cómo pudiste siquiera sugerir eso? No vamos a adorar a un ser sobrenatural sólo porque es más grande y más poderoso que nosotros. Puede que te parezca que somos cobardes al escondernos aquí de los dioses todo este tiempo, pero sé que cada Dorgeshuun preferiría morir antes que someterse al gobierno de cualquier dios.",
    ["Goodbye"] = "Adiós",
    ["*When speaking to Ur-taal or Ur-zek in Dorgesh-kaan*"] = "*Al hablar con Ur-taal o Ur-zek en Dorgesh-kaan*",
    ["I think that Ur-tag is trying to move too quickly. First, he opens the city to humans, and now he wants to invite these dwarves into the city. I think we should exercise more caution in dealing with surface-dwellers."] = "Creo que Ur-tag está intentando moverse demasiado rápido. Primero, abre la ciudad a los humanos y ahora quiere invitar a estos enanos a la ciudad. Creo que deberíamos tener más cautela al tratar con los habitantes de la superficie.",
    ["The dwarves are not surface dwellers. They live in an underground city, like us!"] = "Los enanos no son habitantes de la superficie. ¡Viven en una ciudad subterránea, como nosotros!",
    ["Why does that mean we can trust them? Are you forgetting the machine that nearly destroyed us was made by dwarves?"] = "¿Por qué eso significa que podemos confiar en ellos? ¿Olvidas que la máquina que casi nos destruye fue construida por enanos?",
    ["You shouldn't judge all dwarves because of that!"] = "¡No deberías juzgar a todos los enanos por eso!",
    ["I know that! And I know not all humans want to kill us, but I still never thought we should open the city."] = "¡Lo sé! Y sé que no todos los humanos quieren matarnos, pero aun así nunca pensé que deberíamos abrir la ciudad.",
    ["You can't deny it's done some good. Think of how happy everyone is trying surface foods in the market!"] = "No puedes negar que ha hecho algo bueno. ¡Piense en lo felices que están todos al probar los alimentos de superficie en el mercado!",
    ["I'm not denying that, I just don't think it's worth the risk. Our guards have their work cut out as it is, protecting us from renegade humans, without having to worry about dwarves as well."] = "No lo niego, simplemente no creo que valga la pena correr el riesgo. Nuestros guardias tienen mucho trabajo por delante, protegiéndonos de los humanos renegados, sin tener que preocuparnos también por los enanos.",
    ["Please don't be offended by my friend's attitude, surface- dweller. I'm sure you understand why we need to be cautious."] = "Por favor, no te ofendas por la actitud de mi amigo, habitante de la superficie. Estoy seguro de que comprende por qué debemos ser cautelosos.",
    ["Of course."] = "Por supuesto.",
    ["Headman Ur-tag, I cannot stress enough how important it is that this train link be completed on time. The mining companies have taken out considerable loans..."] = "Jefe Ur-tag, no puedo enfatizar lo suficiente lo importante que es que este enlace de tren se complete a tiempo. Las empresas mineras han obtenido préstamos considerables...",
    ["I understand your concerns, Ambassador, but you must realise that the discoveries must change the whole schedule. To remove them too hurriedly would be a crime against knowledge."] = "Entiendo sus preocupaciones, Embajador, pero debe comprender que los descubrimientos deben cambiar todo el calendario. Eliminarlos demasiado apresuradamente sería un crimen contra el conocimiento.",
    ["Greetings, surface-dweller. Welcome to Dorgesh-Kaan."] = "Saludos, habitante de la superficie. Bienvenido a Dorgesh-Kaan.",
    ["What are you arguing about?"] = "¿De qué estás discutiendo?",
    ["What are you talking about?"] = "¿De qué estás hablando?",
    ["It's the new underground train link being built between our city and the dwarven city of Keldagrim."] = "Es el nuevo enlace de tren subterráneo que se está construyendo entre nuestra ciudad y la ciudad enana de Keldagrim.",
    ["Shh! What if he's a human spy come to steal our dwarven engineering secrets?"] = "¡Shh! ¿Qué pasa si es un espía humano que viene a robar nuestros secretos de ingeniería enanos?",
    ["What can I do in the city?"] = "¿Qué puedo hacer en la ciudad?",
    ["Why don't you visit the market? I hear there is quite a craze for surface foods at the moment, so you might be able to sell something there."] = "¿Por qué no visitas el mercado? He oído que hay una gran moda por los alimentos de superficie en este momento, por lo que es posible que puedas vender algo allí.",
    ["You might also want to visit the caves to the south of the city. There are many monsters to fight there, and Zanik tells me she has also found ways to cross over their heads!"] = "Quizás también quieras visitar las cuevas al sur de la ciudad. ¡Hay muchos monstruos contra los que luchar allí, y Zanik me dice que también ha encontrado formas de pasar por encima de sus cabezas!",
    ["Why did you decide to open the city?"] = "¿Por qué decidiste abrir la ciudad?",
    ["For trade, and for fostering goodwill between races! I am sure that it will benefit both our races."] = "¡Por el comercio y por fomentar la buena voluntad entre razas! Estoy seguro de que beneficiará a ambas razas.",
    ["May I have permission to sell food in the market?"] = "¿Puedo tener permiso para vender comida en el mercado?",
    ["Of course you can."] = "Por supuesto que puedes.",
    ["I want to talk about the Kyzaj Tournament."] = "Quiero hablar sobre el Torneo Kyzaj.",
    ["Yes. Thank you again. You did everything you could and we are safer because of it."] = "Sí. Gracias de nuevo. Hiciste todo lo que pudiste y estamos más seguros gracias a ello.",
    ["How are things going?"] = "¿Cómo van las cosas?",
    ["I was concerned to hear that Graardor rejected Zanik's authority, but we've not had any trouble. The Bandosians cleared out almost immediately and haven't returned. They don't seem interested in us any more. There's always the possibility that they'll come after us again, but we're working on better ways to block their access."] = "Me preocupó escuchar que Graardor rechazó la autoridad de Zanik, pero no hemos tenido ningún problema. Los bandosianos se marcharon casi de inmediato y no han regresado. Ya no parecen interesados ​​en nosotros. Siempre existe la posibilidad de que vuelvan a perseguirnos, pero estamos trabajando en mejores formas de bloquear su acceso.",
    ["What do you think about Zanik?"] = "¿Qué opinas sobre Zanik?",
    ["I can only hope that she finds peace on Yu'biusk, one way or the other. Thank you for giving her that opportunity."] = "Sólo puedo esperar que encuentre la paz en Yu'biusk, de una forma u otra. Gracias por darle esa oportunidad.",
    ["Ah. Player, I presume?"] = "Ah. Player, ¿supongo?",
    ["That's me."] = "Ese soy yo.",
    ["Pleased to meet you. On behalf of the Dorgeshuun Council, I should say how grateful we are that you saved our city."] = "Encantado de conocerte. En nombre del Consejo Dorgeshuun, debo decir lo agradecidos que estamos de que haya salvado nuestra ciudad.",
    ["Ah, Player. It is always a pleasure to meet someone who has become part of Dorgeshuun history. I trust you like the statue we made of you and Zanik?"] = "Ah, Player. Siempre es un placer conocer a alguien que ha pasado a formar parte de la historia de Dorgeshuun. ¿Confío en que te guste la estatua que hicimos de ti y Zanik?",
    ["**Select an option**"] = "**Seleccione una opción**",
    ["It's very good."] = "Es muy bueno.",
    ["Thank you. I will pass on your compliments to the sculptor."] = "Gracias. Transmitiré sus felicitaciones al escultor.",
    ["It looks nothing like me!"] = "¡No se parece en nada a mí!",
    ["I'm afraid the sculptor doesn't have much experience carving human figures. It took him several tries to get the proportions right, so I don't think he can improve much on what he's done."] = "Me temo que el escultor no tiene mucha experiencia tallando figuras humanas. Le tomó varios intentos lograr las proporciones correctas, por lo que no creo que pueda mejorar mucho lo que ha hecho.",
    ["I don't like the pose."] = "No me gusta la pose.",
    ["Oh, I'm. sorry to hear that. Actually, the sculptor made sketches of several different ideas. If you like, I could have him install a statue with a different pose."] = "Oh, lo soy. lamento escuchar eso. En realidad, el escultor hizo bocetos de varias ideas diferentes. Si quieres, podría pedirle que instale una estatua con una pose diferente.",
    ["Yes, please change the statue."] = "Sí, cambia la estatua.",
    ["The pose is alright as it is."] = "La pose está bien tal como está.",
    ["That's good to hear."] = "Es bueno escucharlo.",
    ["*When talking to Urbi in Sophanem.*"] = "*Al hablar con Urbi en Sophanem.*",
    ["Hello there; are you interested in any of my fine daggers? Ideal for slipping under desert robes to give your enemies a nasty surprise..."] = "Hola; ¿Estás interesado en alguno de mis excelentes daggers? Ideal para esconderse bajo las túnicas del desierto y darles a tus enemigos una desagradable sorpresa...",
    ["I'm looking for daggers, yes."] = "Estoy buscando a daggers, sí.",
    ["I'd rather help you in return for better prices."] = "Prefiero ayudarte a cambio de mejores precios.",
    ["I think it will take months for me to return to normal business. If you can wait that long, however, I may have tasks for you."] = "Creo que me llevará meses volver a la normalidad. Sin embargo, si puedes esperar tanto, es posible que tenga tareas para ti.",
    ["No thanks."] = "No, gracias.",
    ["*When spoken to in the correct costume and after wearing the correct outfit, one of these will be said at random*"] = "*Cuando se le hable con el disfraz correcto y después de usar el atuendo correcto, se dirá uno de estos al azar*",
    ["Once, I was a poor man, but then I found a party hat."] = "Una vez fui un hombre pobre, pero luego encontré un sombrero de fiesta.",
    ["There were three goblins in a bar, which one left first?"] = "Había tres duendes en un bar, ¿cuál salió primero?",
    ["Would you like to buy a pewter spoon?"] = "¿Te gustaría comprar una cuchara de peltre?",
    ["In the end, only the three-legged survive."] = "Al final, solo sobreviven los de tres patas.",
    ["I heard that the tall man fears only strong winds."] = "Escuché que el hombre alto solo teme a los vientos fuertes.",
    ["In Canifis the men are known for eating much spam."] = "En Canifis los hombres son conocidos por comer mucho spam.",
    ["I am the egg man, are you one of the egg men?"] = "Yo soy el hombre huevo, ¿eres tú uno de los hombres huevo?",
    ["The sudden appearance of a deaf squirrel is most puzzling, comrade."] = "La repentina aparición de una ardilla sorda es de lo más desconcertante, camarada.",
    ["I believe that it is very rainy in Varrock."] = "Creo que llueve mucho en Varrock.",
    ["The slowest of fishermen catch the swiftest of fish."] = "Los pescadores más lentos capturan los peces más rápidos.",
    ["It is quite easy being green."] = "Es bastante fácil ser ecológico.",
    ["Don't forget to find the jade monkey."] = "No olvides encontrar el mono de jade.",
    ["I am the milkman. My milk is delicious."] = "Soy el lechero. Mi leche es deliciosa.",
    ["The brown cow flies at midnight."] = "La vaca marrón vuela a medianoche.",
    ["I wear the cheese; it does not wear me."] = "Yo uso el queso; no me desgasta.",
    ["How much hide would a hidey-hole hide if a hidey-hole could hide hide?"] = "¿Cuánta piel escondería un escondite si un escondite pudiera esconder?",
    ["*The player responds with*"] = "*el player responde con*",
    ["What?"] = "¿Qué?",
    ["You've found a scroll box!"] = "¡Has encontrado un cuadro de desplazamiento!",
    ["*When not following the instructions*"] = "*Cuando no se siguen las instrucciones*",
    ["I do not believe we have any business, comrade."] = "No creo que tengamos ningún negocio que hacer, camarada.",
    ["You've found a casket!"] = "¡Has encontrado un ataúd!",
    ["The dwarf is hard at work on some sort of highly delicate construction, and doesn't pay you any notice."] = "El enano está trabajando duro en una especie de construcción muy delicada y no te hace caso.",
    ["Sorry laddie, I'm not taking commissions at the moment."] = "Lo siento muchacho, no aceptaré comisiones en este momento.",
    ["I've lost almost all my capital, so I'm just selling tools until I make enough to go back into the jewellery and clockwork business."] = "He perdido casi todo mi capital, así que solo vendo herramientas hasta que gane lo suficiente para volver al negocio de la joyería y la relojería.",
    ["Can I see what you have?"] = "¿Puedo ver lo que tienes?",
    ["Is that your talisman by your foot there?"] = "¿Es ese tu talismán que tienes ahí junto a tu pie?",
    ["Where?"] = "¿Dónde?",
    ["Yoink!"] = "¡Yoink!",
    ["[As he looks away you take the monocle from his top pocket.]"] = "[Mientras él mira hacia otro lado, sacas el monóculo de su bolsillo superior.]",
    ["I'm sorry to hear that."] = "Lamento oír eso.",
    ["Top of the morning. At least I think it's morning. <br>Can I interest you in some crafting supplies?"] = "Lo mejor de la mañana. Al menos creo que es de mañana. <br>¿Puedo interesarte en algunos materiales para manualidades?",
    ["I also have some gem stones for sale. Uncut, but don't ask me where I got them."] = "También tengo algunas piedras preciosas a la venta. Sin cortes, pero no me preguntes de dónde los saqué.",
    ["Where did you get the gemstones?"] = "¿De dónde sacaste las piedras preciosas?",
    ["I told you not to ask me that. <br>Let's just say I've made some friends in questionably legal places."] = "Te dije que no me preguntaras eso. <br>Digamos que he hecho algunos amigos en lugares cuestionablemente legales.",
    ["Does New Varrock ever get sunny?"] = "¿Alguna vez hace sol el nuevo Varrock?",
    ["Who needs daytime when it's always sunny in our hearts?"] = "¿Quién necesita el día cuando siempre hace sol en nuestros corazones?",
    ["Haha! Hahahahaha! <br>Who says zombies don't have a sense of humour?"] = "¡Jaja! ¡Jajajajaja! <br>¿Quién dice que los zombies no tienen sentido del humor?",
    ["No, thanks."] = "No, gracias.",
    ["Hey, Hassan and the leaders were looking for you. Best you talk to them first."] = "Oye, Hassan y los líderes te estaban buscando. Será mejor que hables con ellos primero.",
    ["Complete the Jack of Spades quest to get access to Urluk."] = "Completa la misión Jack of Spades para obtener acceso a Urluk.",
    ["I try to give people help and directions around here."] = "Intento brindar ayuda e indicaciones a la gente por aquí.",
    ["People just make fun of me though."] = "Aunque la gente simplemente se burla de mí.",
    ["What are you talking about? Why would I make fun of you?"] = "¿De qué estás hablando? ¿Por qué me burlaría de ti?",
    ["Well if I told you that you would make fun of me..."] = "Bueno, si te dijera que te burlarías de mí...",
    ["Everyone always makes fun of me behind my back, but camels have brilliant hearing, you know?"] = "Todo el mundo siempre se burla de mí a mis espaldas, pero los camellos tienen un oído brillante, ¿sabes?",
    ["I think I'm starting to see the problem here, I'll get going."] = "Creo que estoy empezando a ver el problema aquí, continuaré.",
    ["No, wait! They make fun of me because I haven't moved in fifty human years. I just like to sit here and smoke cinchor."] = "¡No, espera! Se burlan de mí porque no me he movido en cincuenta años humanos. Sólo me gusta sentarme aquí y fumar cincho.",
    ["How have you kept yourself in food and water? I'm not even mad I'm impressed."] = "¿Cómo te has mantenido en comida y agua? Ni siquiera estoy enojado, estoy impresionado.",
    ["Not gonna lie; I store it in my humps. Haven't needed to eat for decades. You seem nice. Need any advice on what to do round here?"] = "No voy a mentir; Lo guardo en mis jorobas. No he necesitado comer durante décadas. Pareces agradable. ¿Necesitas algún consejo sobre qué hacer por aquí?",
    ["Choose an option: {{anchor"] = "Elige una opción: {{anchor",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["You should try cutting Acadia Trees. You will find them on the raised plateau in the Imperial District, ask a guard if you get lost!"] = "Deberías intentar cortar árboles de Acadia. Los encontrarás en la meseta elevada del Distrito Imperial, ¡pregúntale a un guardia si te pierdes!",
    ["This is a great way to grow your reputation with a faction of your choice."] = "Esta es una excelente manera de hacer crecer tu reputación con la facción que elijas.",
    ["You should try some Thieving in the market place next to us."] = "Deberías probar algo de Thieving en el mercado junto a nosotros.",
    ["You might find that you earn reputation for doing so."] = "Es posible que ganes reputación por hacerlo.",
    ["You should try fishing some Beltfish in the ports district."] = "Deberías intentar pescar algunos Beltfish en el distrito portuario.",
    ["You should go hunt some Plover Birds across the river in Sophanem."] = "Deberías ir a cazar algunos chorlitos al otro lado del río en Sophanem.",
    ["You should do some Shifting Tombs in any of the four districts. Look for the spire."] = "Deberías hacer algunas Tumbas Móviles en cualquiera de los cuatro distritos. Busque la aguja.",
    ["Someone around the city was looking for help. I can't remember the name... [NPC] maybe?"] = "Alguien en la ciudad estaba buscando ayuda. No recuerdo el nombre... ¿[NPC] tal vez?",
    ["You should do one of the City Quests. Try a citizen in need to talk to."] = "Deberías realizar una de las misiones de la ciudad. Pruebe con un ciudadano que necesita hablar.",
    ["You should go do some Slayer in the Sophanem Slayer dungeon. Make sure to pick up some feathers of Ma'at from the general store."] = "Deberías ir a hacer algo de Slayer en la mazmorra Sophanem Slayer. Asegúrate de recoger algunas plumas de Ma'at del general store.",
    ["You should go do some Divination in Sophanem, look for the Luminous Wisps near the river."] = "Deberías hacer algo de Divination en Sophanem, busca los Luminous Wisps cerca del río.",
    ["You should try training your Crafting on the spinning wheel in the Port district."] = "Deberías intentar entrenar a tu Crafting en la rueca en el distrito portuario.",
    ["You should try training your Smithing on the furnace and anvil in the Worker or Port districts."] = "Deberías intentar entrenar a tu Smithing en el horno y el yunque en los distritos de trabajadores o portuarios.",
    ["You should try training your Cooking or Firemaking on the fire pit in the Worker's district."] = "Deberías intentar entrenar tu Cooking o Firemaking en la fogata del Distrito de los Trabajadores.",
    ["What should I aim for?"] = "¿A qué debo aspirar?",
    ["You could do a quest. You aren't well known enough round these parts to be eligible for one, however."] = "Podrías hacer una misión. Sin embargo, no eres lo suficientemente conocido en estos lugares como para ser elegible para uno.",
    ["Level 3 Reputation is required for 'Crocodile Tears'."] = "Se requiere reputación de nivel 3 para 'Crocodile Tears'.",
    ["I can't think of anything more right now, talk to me in a second!"] = "No se me ocurre nada más ahora, ¡háblame en un segundo!",
    ["You should go train your Hunter in order to catch plover birds."] = "Deberías ir a entrenar tu Hunter para atrapar pájaros chorlitos.",
    ["Level 72 Hunter required to catch plover birds."] = "Se requiere nivel 72 Hunter para capturar pájaros chorlitos.",
    ["You should train your Crafting to do Shifting Tombs."] = "Deberías entrenar a tu Crafting para que haga Shifting Tombs.",
    ["Level 50 Crafting required to do Shifting Tombs."] = "Se requiere nivel 50 Crafting para hacer Tumbas Móviles.",
    ["You could do a quest. The citizens of Nardah are undergoing a drought. That could be something to fix beforehand."] = "Podrías hacer una misión. Los ciudadanos de Nardah están sufriendo una sequía. Eso podría ser algo que arreglar de antemano.",
    ["Completion of Spirits of the Elid is required for Crocodile Tears."] = "Es necesario completar Spirits of the Elid para Crocodile Tears.",
    ["You need to improve your slaying to get into the Sophanem Slayer Dungeon."] = "Necesitas mejorar tu habilidad para matar para ingresar a la mazmorra Sophanem Slayer.",
    ["88 Slayer is required for the Sophanem Slayer dungeon."] = "Se requiere 88 Slayer para la mazmorra Sophanem Slayer.",
    ["You should improve your divining ability to utilise the colony in Sophanem."] = "Deberías mejorar tu habilidad de adivinación para utilizar la colonia en Sophanem.",
    ["90 Divination is required to harvest the Sophanem luminous wisp colony."] = "Se requieren 90 Divination para cosechar la colonia de mechones luminosos Sophanem.",
    ["**Urluk:{{anchor|more-things}}** Hmm, well, here's a few more things you could aim for...but I'll let you discover them yourself."] = "**Urluk:{{anchor|more-things}}** Hmm, bueno, aquí hay algunas cosas más a las que podrías aspirar... pero dejaré que las descubras tú mismo.",
    ["Oh! You've done a LOT of things in Menaphos. This deserves a greater reward than a mere cape of the palapa!"] = "¡Oh! Has hecho MUCHAS cosas en Menaphos. ¡Esto merece una recompensa mayor que una simple capa de palapa!",
    ["You have unlocked the '{{Coloury}}' title!|colour=#AAC371}}"] = "¡Has desbloqueado el título '{{Coloury}}'!|color=#AAC371}}",
    ["You have unlocked the '{{Coloury}}' title!|colour=#AAC371|shadow=no}}"] = "¡Has desbloqueado el título '{{Coloury}}'!|color=#AAC371|shadow=no}}",
    ["You know what? I think you're all good."] = "¿Sabes qué? Creo que estáis todos bien.",
    ["Can I get your cape?"] = "¿Puedo conseguir tu capa?",
    ["The Cape of the Palapa is only for those who have seen the world."] = "El Cabo de la Palapa es sólo para aquellos que han visto mundo.",
    ["Do a Shifting Tomb as well as trying out the Woodcutting, Thieving, Mining, Fishing and Hunter in Menaphos and Sophanem to recieve{{Sic}} the cape."] = "Haz una tumba móvil y prueba Woodcutting, Thieving, Mining, Fishing y Hunter en Menaphos y Sophanem para recibir la capa {{Sic}}.",
    ["Congratulations! You have completed: 'Jack of all Menaphos' - Do a bit of everything in Menaphos and claim the cape of the palapa from Urluk."] = "¡Felicitaciones! Has completado: 'Jack of all Menaphos' - Haz un poco de todo en Menaphos y reclama la capa de la palapa de Urluk.",
    ["You have unlocked the cape of the palapa!"] = "¡Has desbloqueado la capa de la palapa!",
    ["Made out of braided cloth strands. You'll never feel exposed again."] = "Hecho de hilos de tela trenzados. Nunca más te sentirás expuesto.",
    ["Do you have any rumours about City Quests?"] = "¿Tienes algún rumor sobre City Quests?",
    ["Someone around the city was looking for help. I can't remember the name.... [NPC] maybe?"] = "Alguien en la ciudad estaba buscando ayuda. No recuerdo el nombre.... ¿[NPC] tal vez?",
    ["You should do one of the city Quests. From time to time a citizen will need help, I guarantee it."] = "Deberías hacer una de las misiones de la ciudad. De vez en cuando un ciudadano necesitará ayuda, lo garantizo.",
    ["How can I understand you?"] = "¿Cómo puedo entenderte?",
    ["During my travels, I found an amulet of humanspeak. I have to say it has come in very handy in stopping you lot from attacking me."] = "Durante mis viajes, encontré un amuleto de habla humana. Debo decir que ha sido muy útil para evitar que me ataquen.",
    ["Good day to you."] = "Buenos días para ti.",
    ["It's not that good, it's a bit warm."] = "No está tan bueno, hace un poco de calor.",
    ["The curse has been removed. Word around the town is that you were the one who helped remove it."] = "La maldición ha sido eliminada. Se dice en la ciudad que tú fuiste quien ayudó a eliminarlo.",
    ["Yes that is correct. The spirits of the Elid cursed the town for throwing away a statue to Elidinis. I got it"] = "Sí, eso es correcto. Los espíritus de los Elid maldijeron a la ciudad por arrojar una estatua a Elidinis. lo tengo",
    ["Well we thank you. You’re pretty much a local hero now."] = "Bueno, te lo agradecemos. Ahora eres prácticamente un héroe local.",
    ["A divine wolf pup stares up at you. His expression is a mixture of curiosity and apprehension."] = "Un cachorro de lobo divino te mira fijamente. Su expresión es una mezcla de curiosidad y aprensión.",
    ["Hello there, little one."] = "Hola, pequeña.",
    ["Are you alright? Who are you?"] = "¿Estás bien? ¿Quién eres?",
    ["Who are you?"] = "¿Quién eres?",
    ["I'm Player. Do you know your name?"] = "Soy Player. ¿Sabes tu nombre?",
    ["Know your...name. Yes."] = "Conoce tu... nombre. Sí.",
    ["Utu. I am Utu."] = "Utu. Soy Utu.",
    ["What are you doing here, Utu?"] = "¿Qué haces aquí, Utu?",
    ["What are you doing here, Player?"] = "¿Qué haces aquí, Player?",
    ["I was hoping I could explore the history of this temple."] = "Esperaba poder explorar la historia de este templo.",
    ["This temple...I protect this temple. It was my duty. It is my duty."] = "Este templo... Yo protejo este templo. Era mi deber. Es mi deber.",
    ["Do you remember anything, aside from your name and your duty?"] = "¿Recuerdas algo, aparte de tu nombre y tu deber?",
    ["My memories have flittered away, like autumn leaves on the wind. I am barren in their absence."] = "Mis recuerdos se han ido volando, como hojas de otoño en el viento. Soy estéril en su ausencia.",
    ["I could excavate the temple. See what I can find. Maybe I'll come across something that will help restore your memories."] = "Podría excavar el templo. A ver que puedo encontrar. Tal vez encuentre algo que le ayude a restaurar sus recuerdos.",
    ["Very well. It shall be your duty. Explore the history of the temple. Help me restore my memories."] = "Muy bien. Será tu deber. Explora la historia del templo. Ayúdame a restaurar mis recuerdos.",
    ["I'll get started, then. Thank you, Utu."] = "Entonces empezaré. Gracias, Utu.",
    ["Thank you, Player."] = "Gracias, Player.",
    ["Hello, Player."] = "Hola, Player.",
    ["Greetings, little one."] = "Saludos, pequeña.",
    ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
    ["I remember little of myself. Of my past. This temple is all I know."] = "Recuerdo poco de mí. De mi pasado. Este templo es todo lo que conozco.",
    ["Have you ever been inside?"] = "¿Has estado alguna vez dentro?",
    ["No. When I approach its door a voice echoes across my mind. A warning. A command. To never enter the temple's depths."] = "No. Cuando me acerco a su puerta, una voz hace eco en mi mente. Una advertencia. Un comando. Nunca entrar en las profundidades del templo.",
    ["A voice in your head? Whose voice?"] = "¿Una voz en tu cabeza? ¿La voz de quién?",
    ["I do not know. But it is familiar."] = "No lo sé. Pero me resulta familiar.",
    ["Perhaps it is my own."] = "Quizás sea mío.",
    ["I woke before the Lunar Wheel many cycles ago, knowing naught but my name and my duty: to watch over this temple."] = "Me desperté ante la Rueda Lunar hace muchos ciclos, sin saber nada más que mi nombre y mi deber: velar por este templo.",
    ["In truth, it is more than duty that keeps me here. I am bound to this place. To its past. Its secrets. To the very stone into which it is carved."] = "En verdad, es más que el deber lo que me mantiene aquí. Estoy atado a este lugar. A su pasado. Sus secretos. A la misma piedra en la que está tallado.",
    ["What do you mean? You can't leave?"] = "¿Qué quieres decir? ¿No puedes irte?",
    ["Can the moon flee the sky, to walk with mortals upon the land?"] = "¿Puede la luna huir del cielo para caminar con los mortales sobre la tierra?",
    ["From the moment I awoke, an immeasurable sorrow has raged within my soul. Shame. Regret. Like a parasite, slowly consuming me from within."] = "Desde el momento en que desperté, un dolor inconmensurable ha arrasado mi alma. Lástima. Arrepentirse. Como un parásito, consumiéndome lentamente desde dentro.",
    ["I must know its cause. Until my memories have been restored, I will never know peace."] = "Debo saber su causa. Hasta que mis recuerdos no sean restaurados, nunca conoceré la paz.",
    ["You may not like what you learn."] = "Puede que no te guste lo que aprendes.",
    ["**Utu: ** So be it. No knowledge could cause such suffering as this."] = "**Utu: ** Que así sea. Ningún conocimiento podría causar tal sufrimiento.",
    ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
    ["This place stirs many feelings. Hollowness. Shame. Disgrace."] = "Este lugar despierta muchos sentimientos. Hueco. Lástima. Desgracia.",
    ["Why's that?"] = "¿Por qué?",
    ["I do not know. Perhaps I did, once."] = "No lo sé. Quizás lo hice, alguna vez.",
    ["It is lonely, standing watch over this temple. Two humans visited before you. One your size. One nearer mine. I had only recently awoken. I dared not reveal myself to them."] = "Es muy solitario estar vigilando este templo. Dos humanos te visitaron antes. Uno de tu talla. Uno más cerca del mío. Me había despertado recientemente. No me atrevía a revelarme a ellos.",
    ["I has been less lonely, since meeting you."] = "Me he sentido menos solo desde que te conocí.",
    ["I'm glad to hear that."] = "Me alegra oír eso.",
    ["This is the great temple of Akshur-Nakkir. Jewel of the Nakkirian people. Seat of the divine."] = "Este es el gran templo de Akshur-Nakkir. Joya del pueblo Nakkirian. Asiento de lo divino.",
    ["We were as gods to the people who lived here. They came to us with offerings and worship. We granted them our blessings in return."] = "Éramos como dioses para la gente que vivía aquí. Vinieron a nosotros con ofrendas y adoración. A cambio, les concedimos nuestras bendiciones.",
    ["Those who live here now call this place 'Moonrise'."] = "Quienes viven aquí ahora llaman a este lugar 'Salida de la Luna'.",
    ["An apt name, for we held the moon in high regard."] = "Un nombre apropiado, porque teníamos en alta estima a la luna.",
    ["The Lunar Wheel was a gift from Guthix, the slumbering god, himself. Carved by his own hands when he shaped this world. I cannot recall the true extent of its power."] = "La Rueda Lunar fue un regalo del propio Guthix, el dios dormido. Tallado por sus propias manos cuando dio forma a este mundo. No puedo recordar el verdadero alcance de su poder.",
    ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
    ["Bye."] = "Adiós.",
    ["Farewell, Player."] = "Adiós, Player.",
    ["Moonlight guide your path."] = "La luz de la luna guía tu camino.",
    ["How are you feeling, Utu?"] = "¿Cómo te sientes, Utu?",
    ["The revelations you have uncovered are a lot to take in. There is much to reflect on. Much to ponder."] = "Las revelaciones que has descubierto son mucho para asimilar. Hay mucho sobre lo que reflexionar. Mucho para reflexionar.",
    ["I require time. Please, Player, {{Sic|Leave}} me to my thoughts."] = "Necesito tiempo. Por favor, Player, {{Sic|Leave}}, déjame ir a mis pensamientos.",
    ["Very well."] = "Muy bien.",
    ["I haven't found any clues to your past yet, but I'm making progress."] = "Aún no he encontrado ninguna pista sobre tu pasado, pero estoy progresando.",
    ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
    ["Shadows of the Colossi."] = "Sombras de los colosos.",
    ["Path of the Initiate"] = "Camino del Iniciado",
    ["Cult Classic."] = "Clásico de culto.",
    ["Inside You There Are Two Wolves."] = "Dentro de ti hay dos lobos.",
}

